// Python-compatibility helpers: code-point aware string utilities and
// CPython-compatible number formatting (repr of float, str of int).

// Convert a JS string to an array of single-code-point strings so that
// indexing/length semantics match Python's str.
export function cps(str) {
  return Array.from(str);
}

export function cpOf(ch) {
  return ch.codePointAt(0);
}

export function isDigit(ch) {
  return ch >= '0' && ch <= '9';
}

export function isHexDigit(ch) {
  return (ch >= '0' && ch <= '9') || (ch >= 'a' && ch <= 'f') || (ch >= 'A' && ch <= 'F');
}

export function isAlphaNum(ch) {
  return (ch >= '0' && ch <= '9') || (ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z');
}

// CPython repr() of a double (shortest round-trip representation).
// Only finite numbers are handled here.
export function pythonFloatRepr(x) {
  let sign = '';
  let a = x;
  if (a < 0 || (a === 0 && 1 / a < 0)) {
    sign = '-';
    a = -a;
  }
  if (a === 0) return sign + '0.0';
  // Find the shortest precision that round-trips.
  let digits = null;
  let exp10 = 0;
  for (let p = 1; p <= 17; p++) {
    const t = a.toExponential(p - 1);
    if (Number(t) === a) {
      const eIdx = t.indexOf('e');
      const mant = t.slice(0, eIdx);
      exp10 = parseInt(t.slice(eIdx + 1), 10);
      digits = mant.replace('.', '');
      // strip trailing zeros that toExponential may keep (it shouldn't for
      // the shortest p, but be safe)
      while (digits.length > 1 && digits.endsWith('0')) digits = digits.slice(0, -1);
      break;
    }
  }
  if (digits === null) {
    const t = a.toExponential(16);
    const eIdx = t.indexOf('e');
    exp10 = parseInt(t.slice(eIdx + 1), 10);
    digits = t.slice(0, eIdx).replace('.', '');
    while (digits.length > 1 && digits.endsWith('0')) digits = digits.slice(0, -1);
  }
  const len = digits.length;
  let out;
  if (exp10 >= -4 && exp10 <= 15) {
    // fixed notation
    if (exp10 >= len - 1) {
      out = digits + '0'.repeat(exp10 - len + 1) + '.0';
    } else if (exp10 >= 0) {
      out = digits.slice(0, exp10 + 1) + '.' + digits.slice(exp10 + 1);
    } else {
      out = '0.' + '0'.repeat(-exp10 - 1) + digits;
    }
  } else {
    // exponential notation: d[.ddd]e±XX (at least two exponent digits)
    let mant = digits[0];
    if (len > 1) mant += '.' + digits.slice(1);
    const es = exp10 < 0 ? '-' : '+';
    let ea = String(Math.abs(exp10));
    if (ea.length < 2) ea = '0' + ea;
    out = mant + 'e' + es + ea;
  }
  return sign + out;
}

// PyYAML SafeRepresenter.represent_float behaviour.
export function representFloat(x) {
  if (Number.isNaN(x)) return '.nan';
  if (x === Infinity) return '.inf';
  if (x === -Infinity) return '-.inf';
  let value = pythonFloatRepr(x);
  if (!value.includes('.') && !value.includes('e')) {
    value += '.0';
  } else if (value.includes('e') && !value.includes('.')) {
    value = value.replace('e', '.0e');
  }
  return value;
}

// str(int) for our integer values (Number in safe range or BigInt).
export function representInt(v) {
  if (typeof v === 'bigint') return v.toString();
  return String(v);
}

// YAML node tree (composition level) and the constructed-value wrapper
// classes that preserve Python type information through to the dumper.

export class ScalarNode {
  constructor(tag, value, style, plain, startMark, endMark) {
    this.kind = 'scalar';
    this.tag = tag;
    this.value = value;
    this.style = style;   // null (plain), "'", '"', '|', '>'
    this.plain = plain;
    this.startMark = startMark;
    this.endMark = endMark;
  }
}

export class SequenceNode {
  constructor(tag, items, flowStyle) {
    this.kind = 'sequence';
    this.tag = tag;
    this.value = items;
    this.flowStyle = flowStyle;
  }
}

export class MappingNode {
  constructor(tag, pairs, flowStyle) {
    this.kind = 'mapping';
    this.tag = tag;
    this.value = pairs; // [[keyNode, valueNode], ...]
    this.flowStyle = flowStyle;
  }
}

// ---- Constructed value wrappers (Python-level types) ----

// YAML floats are kept distinct from ints (JS loses the int/float
// distinction for integral values).
export class YAMLFloat {
  constructor(value) { this.value = value; }
}

export class YAMLDate {
  constructor(year, month, day) {
    this.year = year; this.month = month; this.day = day;
  }
}

export class YAMLDateTime {
  constructor(year, month, day, hour, minute, second, microsecond, tzMinutes) {
    this.year = year; this.month = month; this.day = day;
    this.hour = hour; this.minute = minute; this.second = second;
    this.microsecond = microsecond;
    this.tzMinutes = tzMinutes; // null = naive, otherwise signed offset minutes
  }
}

export class YAMLBytes {
  constructor(bytes) { this.bytes = bytes; } // Uint8Array
}

// Ordered map with Python dict semantics (first-key position kept,
// later assignment overwrites the value).
export class YAMLMap {
  constructor() {
    this.pairs = [];
    this.index = new Map();
  }
  set(key, value) {
    const hk = pyHashKey(key);
    if (this.index.has(hk)) {
      this.pairs[this.index.get(hk)][1] = value;
    } else {
      this.index.set(hk, this.pairs.length);
      this.pairs.push([key, value]);
    }
  }
}

export class YAMLSet {
  constructor() {
    this.keys = [];
    this.index = new Map();
  }
  add(key) {
    const hk = pyHashKey(key);
    if (!this.index.has(hk)) {
      this.index.set(hk, this.keys.length);
      this.keys.push(key);
    }
  }
}

// A Python tuple (produced by !!omap / !!pairs).
export class YAMLTuple {
  constructor(items) { this.items = items; }
}

export class ConstructorError extends Error {
  constructor(context, contextMark, problem, problemMark) {
    let msg = '';
    if (context) msg += context + '\n';
    if (contextMark) msg += '  in "<unicode string>", ' + contextMark + '\n';
    msg += problem;
    if (problemMark) msg += '\n  in "<unicode string>", ' + problemMark;
    super(msg);
    this.name = 'yaml.constructor.ConstructorError';
  }
}

function pad2(n) { return n < 10 ? '0' + n : String(n); }
function pad4(n) {
  let s = String(n);
  while (s.length < 4) s = '0' + s;
  return s;
}

export function dateIso(d) {
  return pad4(d.year) + '-' + pad2(d.month) + '-' + pad2(d.day);
}

export function dateTimeIso(dt) {
  let s = dateIso(dt) + ' ' + pad2(dt.hour) + ':' + pad2(dt.minute) + ':' + pad2(dt.second);
  if (dt.microsecond) {
    let us = String(dt.microsecond);
    while (us.length < 6) us = '0' + us;
    s += '.' + us;
  }
  if (dt.tzMinutes !== null) {
    const sign = dt.tzMinutes < 0 ? '-' : '+';
    const abs = Math.abs(dt.tzMinutes);
    s += sign + pad2(Math.floor(abs / 60)) + ':' + pad2(abs % 60);
  }
  return s;
}

// Python-style hash/equality key for mapping keys.
// Throws ConstructorError for unhashable types (list/dict/set).
export function pyHashKey(v) {
  if (v === null) return 'null:';
  if (typeof v === 'boolean') return 'num:' + (v ? 1 : 0);
  if (typeof v === 'number') return 'num:' + v;        // ints only
  if (typeof v === 'bigint') return 'num:' + v.toString();
  if (typeof v === 'string') return 'str:' + v;
  if (v instanceof YAMLFloat) {
    const x = v.value;
    if (Number.isInteger(x) && Math.abs(x) <= Number.MAX_SAFE_INTEGER) {
      // integral floats hash equal to the corresponding int (1.0 == 1)
      if (x === 0) return 'num:0';
      return 'num:' + x;
    }
    return 'float:' + String(x);
  }
  if (v instanceof YAMLDate) return 'date:' + dateIso(v);
  if (v instanceof YAMLDateTime) return 'dt:' + dateTimeIso(v);
  if (v instanceof YAMLBytes) {
    let s = '';
    for (const b of v.bytes) s += String.fromCharCode(b);
    return 'bytes:' + s;
  }
  if (v instanceof YAMLTuple) {
    return 'tuple:(' + v.items.map(pyHashKey).join(',') + ')';
  }
  throw new ConstructorError(null, null, 'found unhashable key', null);
}

// Character reader over the input string, operating on Unicode code points
// (matching Python string semantics). Normalizes line breaks and validates
// printability like PyYAML's Reader.

export class Mark {
  constructor(index, line, column) {
    this.index = index;
    this.line = line;     // 0-based
    this.column = column; // 0-based
  }
  toString() {
    return `line ${this.line + 1}, column ${this.column + 1}`;
  }
}

export class YamlError extends Error {
  constructor(message) {
    super(message);
    this.name = 'yaml.YAMLError';
  }
}

export class ReaderError extends YamlError {
  constructor(character, position) {
    super(`unacceptable character ${character}: invalid characters`);
    this.name = 'yaml.reader.ReaderError';
  }
}

function isPrintable(ch) {
  const c = ch.codePointAt(0);
  return c === 0x09 || c === 0x0a || c === 0x0d ||
    (c >= 0x20 && c <= 0x7e) || c === 0x85 ||
    (c >= 0xa0 && c <= 0xd7ff) ||
    (c >= 0xe000 && c <= 0xfffd) ||
    (c >= 0x10000 && c <= 0x10ffff);
}

export class Reader {
  constructor(src) {
    let chars = Array.from(src);
    if (chars.length > 0 && chars[0] === '﻿') chars.shift();
    const out = [];
    for (let i = 0; i < chars.length; i++) {
      const ch = chars[i];
      if (!isPrintable(ch)) {
        throw new ReaderError('#x' + ch.codePointAt(0).toString(16).toUpperCase(), i);
      }
      if (ch === '\r') {
        if (i + 1 < chars.length && chars[i + 1] === '\n') {
          out.push('\n');
          i++;
        } else {
          out.push('\n');
        }
      } else {
        out.push(ch);
      }
    }
    this.buffer = out;
    this.index = 0;
    this.line = 0;
    this.column = 0;
  }

  peek(offset = 0) {
    const i = this.index + offset;
    if (i < this.buffer.length) return this.buffer[i];
    return '\0';
  }

  prefix(length = 1) {
    let s = '';
    for (let i = 0; i < length; i++) s += this.peek(i);
    return s;
  }

  forward(length = 1) {
    for (let i = 0; i < length; i++) {
      const ch = this.peek();
      this.index++;
      if (ch === '\n' || ch === '' || ch === ' ' || ch === ' ') {
        this.line++;
        this.column = 0;
      } else if (ch !== '\0') {
        this.column++;
      }
    }
  }

  getMark() {
    return new Mark(this.index, this.line, this.column);
  }
}

// Token types produced by the scanner.

export class Token {
  constructor(kind, startMark, endMark) {
    this.kind = kind;
    this.startMark = startMark;
    this.endMark = endMark;
  }
}

export function streamStart(mark) { return new Token('stream-start', mark, mark); }
export function streamEnd(mark) { return new Token('stream-end', mark, mark); }
export function directive(name, value, startMark, endMark) {
  const t = new Token('directive', startMark, endMark);
  t.name = name; t.value = value;
  return t;
}
export function simpleToken(kind, startMark, endMark) { return new Token(kind, startMark, endMark); }
export function aliasToken(value, startMark, endMark) {
  const t = new Token('alias', startMark, endMark); t.value = value; return t;
}
export function anchorToken(value, startMark, endMark) {
  const t = new Token('anchor', startMark, endMark); t.value = value; return t;
}
export function tagToken(handle, suffix, startMark, endMark) {
  const t = new Token('tag', startMark, endMark); t.handle = handle; t.suffix = suffix; return t;
}
export function scalarToken(value, plain, startMark, endMark, style = null) {
  const t = new Token('scalar', startMark, endMark);
  t.value = value; t.plain = plain; t.style = style;
  return t;
}

