// Implicit tag resolution for plain scalars, mirroring PyYAML's Resolver
// (YAML 1.1 schema as implemented by PyYAML). No regular expressions are
// used; the PyYAML regex patterns are reimplemented as character scanners.

export const TAG_STR = 'tag:yaml.org,2002:str';
export const TAG_SEQ = 'tag:yaml.org,2002:seq';
export const TAG_MAP = 'tag:yaml.org,2002:map';
export const TAG_NULL = 'tag:yaml.org,2002:null';
export const TAG_BOOL = 'tag:yaml.org,2002:bool';
export const TAG_INT = 'tag:yaml.org,2002:int';
export const TAG_FLOAT = 'tag:yaml.org,2002:float';
export const TAG_TIMESTAMP = 'tag:yaml.org,2002:timestamp';
export const TAG_MERGE = 'tag:yaml.org,2002:merge';
export const TAG_VALUE = 'tag:yaml.org,2002:value';
export const TAG_BINARY = 'tag:yaml.org,2002:binary';
export const TAG_SET = 'tag:yaml.org,2002:set';
export const TAG_OMAP = 'tag:yaml.org,2002:omap';
export const TAG_PAIRS = 'tag:yaml.org,2002:pairs';
export const TAG_PREFIX = 'tag:yaml.org,2002:';

const BOOL_WORDS = ['yes', 'Yes', 'YES', 'no', 'No', 'NO',
  'true', 'True', 'TRUE', 'false', 'False', 'FALSE',
  'on', 'On', 'ON', 'off', 'Off', 'OFF'];

function isDigit(ch) { return ch >= '0' && ch <= '9'; }

// [-+]?0b[0-1_]+ | [-+]?0[0-7_]+ | [-+]?(0|[1-9][0-9_]*) |
// [-+]?0x[0-9a-fA-F_]+ | [-+]?[1-9][0-9_]*(:[0-5]?[0-9])+
export function isIntScalar(v) {
  let s = v;
  if (s.startsWith('-') || s.startsWith('+')) s = s.slice(1);
  if (s.length === 0) return false;
  if (s.startsWith('0b')) {
    const rest = s.slice(2);
    if (rest.length === 0) return false;
    return allOf(rest, ch => ch === '0' || ch === '1' || ch === '_');
  }
  if (s.startsWith('0x')) {
    const rest = s.slice(2);
    if (rest.length === 0) return false;
    return allOf(rest, isHexDigit);
  }
  if (s.includes(':')) {
    return isSexagesimal(s, false);
  }
  if (s.length > 1 && s[0] === '0') {
    return allOf(s.slice(1), ch => (ch >= '0' && ch <= '7') || ch === '_');
  }
  if (s === '0') return true;
  if (s[0] >= '1' && s[0] <= '9') {
    return allOf(s.slice(1), ch => isDigit(ch) || ch === '_');
  }
  return false;
}

// [1-9][0-9_]*(:[0-5]?[0-9])+  (sign already stripped)
// when allowDot: trailing '.[0-9_]*' permitted (sexagesimal float)
function isSexagesimal(s, allowDot) {
  let parts;
  if (allowDot) {
    const dot = s.lastIndexOf('.');
    const frac = s.slice(dot + 1);
    if (!allOf(frac, ch => isDigit(ch) || ch === '_')) return false;
    parts = s.slice(0, dot).split(':');
  } else {
    parts = s.split(':');
  }
  if (parts.length < 2) return false;
  const first = parts[0];
  if (!(first[0] >= '1' && first[0] <= '9')) return false;
  if (!allOf(first.slice(1), ch => isDigit(ch) || ch === '_')) return false;
  for (let i = 1; i < parts.length; i++) {
    const p = parts[i];
    if (p.length === 0 || p.length > 2) return false;
    if (!allOf(p, isDigit)) return false;
    if (p.length === 2 && !(p[0] >= '0' && p[0] <= '5')) return false;
  }
  return true;
}

// [-+]?([0-9][0-9_]*)\.[0-9_]*([eE][-+][0-9]+)?
// | \.[0-9][0-9_]*([eE][-+][0-9]+)?
// | [-+]?[0-9][0-9_]*(:[0-5]?[0-9])+\.[0-9_]*
// | [-+]?\.(inf|Inf|INF)
// | \.(nan|NaN|NAN)
export function isFloatScalar(v) {
  if (v === '.nan' || v === '.NaN' || v === '.NAN') return true;
  let s = v;
  if (s.startsWith('-') || s.startsWith('+')) s = s.slice(1);
  if (s === '.inf' || s === '.Inf' || s === '.INF') return true;
  if (s.length === 0) return false;
  if (s.includes(':')) {
    return isSexagesimal(s, true) && s.includes('.');
  }
  let m = s;
  // optional exponent (sign required)
  const eIdx = indexOfExp(m);
  if (eIdx >= 0) {
    const exp = m.slice(eIdx + 1);
    if (!(exp.startsWith('-') || exp.startsWith('+'))) return false;
    const ed = exp.slice(1);
    if (ed.length === 0 || !allOf(ed, isDigit)) return false;
    m = m.slice(0, eIdx);
  }
  const dot = m.indexOf('.');
  if (dot < 0) return false;
  const intPart = m.slice(0, dot);
  const fracPart = m.slice(dot + 1);
  if (intPart.length === 0) {
    // \.[0-9][0-9_]*  (note: no sign allowed before the leading dot,
    // the sign was stripped above only for the other alternatives)
    if (v.startsWith('-') || v.startsWith('+')) return false;
    if (fracPart.length === 0) return false;
    if (!isDigit(fracPart[0])) return false;
    return allOf(fracPart.slice(1), ch => isDigit(ch) || ch === '_');
  }
  // [0-9][0-9_]*\.[0-9_]*
  if (!isDigit(intPart[0])) return false;
  if (!allOf(intPart.slice(1), ch => isDigit(ch) || ch === '_')) return false;
  return allOf(fracPart, ch => isDigit(ch) || ch === '_');
}

function indexOfExp(s) {
  for (let i = 0; i < s.length; i++) {
    if (s[i] === 'e' || s[i] === 'E') return i;
  }
  return -1;
}

export function isBoolScalar(v) {
  return BOOL_WORDS.includes(v);
}

export function isNullScalar(v) {
  return v === '~' || v === 'null' || v === 'Null' || v === 'NULL' || v === '';
}

// [0-9]{4}-[0-9]{2}-[0-9]{2}
function isYmdTimestamp(v) {
  if (v.length !== 10) return false;
  for (let i = 0; i < 10; i++) {
    if (i === 4 || i === 7) { if (v[i] !== '-') return false; }
    else if (!isDigit(v[i])) return false;
  }
  return true;
}

// [0-9]{4}-[0-9]{1,2}-[0-9]{1,2}([Tt]|[ \t]+)[0-9]{1,2}:[0-9]{2}:[0-9]{2}
//   (\.[0-9]*)?([ \t]*(Z|[-+][0-9]{1,2}(:[0-9]{2})?))?
function isFullTimestamp(v) {
  let i = 0;
  const n = v.length;
  const digits = (min, max) => {
    let c = 0;
    while (i < n && isDigit(v[i]) && c < max) { i++; c++; }
    return c >= min;
  };
  if (!digits(4, 4)) return false;
  if (i >= n || v[i] !== '-') return false; i++;
  if (!digits(1, 2)) return false;
  if (i >= n || v[i] !== '-') return false; i++;
  if (!digits(1, 2)) return false;
  // separator
  if (i >= n) return false;
  if (v[i] === 'T' || v[i] === 't') { i++; }
  else if (v[i] === ' ' || v[i] === '\t') {
    while (i < n && (v[i] === ' ' || v[i] === '\t')) i++;
  } else return false;
  if (!digits(1, 2)) return false;
  if (i >= n || v[i] !== ':') return false; i++;
  if (!digits(2, 2)) return false;
  if (i >= n || v[i] !== ':') return false; i++;
  if (!digits(2, 2)) return false;
  if (i < n && v[i] === '.') {
    i++;
    while (i < n && isDigit(v[i])) i++;
  }
  // timezone
  if (i < n) {
    while (i < n && (v[i] === ' ' || v[i] === '\t')) i++;
    if (i >= n) return true;
    if (v[i] === 'Z') { i++; return i === n; }
    if (v[i] === '-' || v[i] === '+') {
      i++;
      if (!digits(1, 2)) return false;
      if (i < n && v[i] === ':') {
        i++;
        if (!digits(2, 2)) return false;
      }
      return i === n;
    }
    return false;
  }
  return true;
}

export function isTimestampScalar(v) {
  return isYmdTimestamp(v) || isFullTimestamp(v);
}

// Resolve a scalar to its tag. plainAllowed corresponds to PyYAML's
// implicit[0]; quoted/empty-style scalars resolve to str.
export function resolveScalarTag(value, plainAllowed) {
  if (!plainAllowed) return TAG_STR;
  // Order and first-char dispatch of PyYAML's implicit resolvers.
  const first = value.length ? value[0] : '';
  const candidates = [];
  const has = chars => chars.includes(first);
  if (has('yYnNtTfFoO')) candidates.push([TAG_BOOL, isBoolScalar]);
  if (has('-+.0123456789')) candidates.push([TAG_FLOAT, isFloatScalar]);
  if (has('-+0123456789')) candidates.push([TAG_INT, isIntScalar]);
  if (has('<')) candidates.push([TAG_MERGE, v => v === '<<']);
  if (has('~nN') || value === '') candidates.push([TAG_NULL, isNullScalar]);
  if (has('0123456789')) candidates.push([TAG_TIMESTAMP, isTimestampScalar]);
  if (has('=')) candidates.push([TAG_VALUE, v => v === '=']);
  for (const [tag, test] of candidates) {
    if (test(value)) return tag;
  }
  return TAG_STR;
}

function allOf(s, pred) {
  for (const ch of s) if (!pred(ch)) return false;
  return true;
}

function isHexDigit(ch) {
  return (ch >= '0' && ch <= '9') || (ch >= 'a' && ch <= 'f') || (ch >= 'A' && ch <= 'F');
}

// Parser + composer: turns the token stream into a node tree.
// Behaviourally mirrors PyYAML's parser.py + composer.py, including
// implicit tag resolution at composition time and anchor handling.

import { Scanner, ScannerError } from './scanner.mjs';
import { YamlError } from './reader.mjs';
import { ScalarNode, SequenceNode, MappingNode } from './nodes.mjs';
import { resolveScalarTag, TAG_SEQ, TAG_MAP, TAG_PREFIX } from './resolver.mjs';

export class ParserError extends YamlError {
  constructor(context, contextMark, problem, problemMark) {
    let msg = '';
    if (context) msg += context + '\n';
    if (contextMark) msg += '  in "<unicode string>", ' + contextMark + '\n';
    msg += problem;
    if (problemMark) msg += '\n  in "<unicode string>", ' + problemMark;
    super(msg);
    this.name = 'yaml.parser.ParserError';
  }
}

export class ComposerError extends YamlError {
  constructor(context, contextMark, problem, problemMark) {
    let msg = '';
    if (context) msg += context + '\n';
    if (contextMark) msg += '  in "<unicode string>", ' + contextMark + '\n';
    msg += problem;
    if (problemMark) msg += '\n  in "<unicode string>", ' + problemMark;
    super(msg);
    this.name = 'yaml.composer.ComposerError';
  }
}

const DEFAULT_TAGS = { '!': '!', '!!': 'tag:yaml.org,2002:' };

export function parseStream(src) {
  const p = new Parser(src);
  return p.getSingleNode();
}

class Parser {
  constructor(src) {
    this.scanner = new Scanner(src);
    this.anchors = new Map();
    this.tagHandles = { ...DEFAULT_TAGS };
  }

  checkToken(...kinds) { return this.scanner.checkToken(...kinds); }
  peekToken() { return this.scanner.peekToken(); }
  getToken() { return this.scanner.getToken(); }

  getSingleNode() {
    // STREAM-START
    this.getToken();
    let node = null;
    if (!this.checkToken('stream-end')) {
      node = this.parseDocument();
    }
    if (!this.checkToken('stream-end')) {
      const token = this.peekToken();
      throw new ComposerError('expected a single document in the stream',
        node ? node.startMark : token.startMark,
        'but found another document', token.startMark);
    }
    this.getToken(); // STREAM-END
    return node;
  }

  parseDocument() {
    this.processDirectives();
    if (!this.checkToken('document-start')) {
      const token = this.peekToken();
      throw new ParserError(null, null,
        `expected '<document start>', but found '${token.kind}'`, token.startMark);
    }
    this.getToken(); // DOCUMENT-START
    this.anchors = new Map();
    let node;
    if (this.checkToken('directive', 'document-start', 'document-end', 'stream-end')) {
      const token = this.peekToken();
      node = new ScalarNode(null, '', null, true, token.startMark, token.endMark);
      node.tag = resolveScalarTag('', true);
    } else {
      node = this.parseNode();
    }
    if (this.checkToken('document-end')) {
      this.getToken();
    }
    return node;
  }

  processDirectives() {
    const handles = {};
    let yamlVersion = null;
    while (this.checkToken('directive')) {
      const token = this.getToken();
      if (token.name === 'YAML') {
        if (yamlVersion !== null) {
          throw new ParserError(null, null, 'found duplicate YAML directive', token.startMark);
        }
        yamlVersion = token.value;
        if (yamlVersion[0] !== 1) {
          throw new ParserError(null, null,
            'found incompatible YAML document (version 1.* is required)', token.startMark);
        }
      } else if (token.name === 'TAG') {
        const [handle, prefix] = token.value;
        if (handle in handles) {
          throw new ParserError(null, null,
            `duplicate tag handle '${handle}'`, token.startMark);
        }
        handles[handle] = prefix;
      }
    }
    this.tagHandles = { ...DEFAULT_TAGS, ...handles };
  }

  parseNode(block = false, indentlessSequence = false) {
    let anchor = null;
    let tag = null;
    let startMark = null;
    let token;

    if (this.checkToken('alias')) {
      token = this.getToken();
      if (!this.anchors.has(token.value)) {
        throw new ComposerError(null, null,
          `found undefined alias '${token.value}'`, token.startMark);
      }
      return this.anchors.get(token.value);
    }

    if (this.checkToken('anchor')) {
      token = this.getToken();
      startMark = token.startMark;
      anchor = token.value;
      if (this.checkToken('tag')) {
        token = this.getToken();
        tag = token;
      }
    } else if (this.checkToken('tag')) {
      token = this.getToken();
      startMark = token.startMark;
      tag = token;
      if (this.checkToken('anchor')) {
        token = this.getToken();
        anchor = token.value;
      }
    }

    let resolvedTag = null;
    if (tag !== null) {
      if (tag.handle !== null) {
        if (!(tag.handle in this.tagHandles)) {
          throw new ParserError('while parsing a node', startMark,
            `found undefined tag handle '${tag.handle}'`, tag.startMark);
        }
        resolvedTag = this.tagHandles[tag.handle] + tag.suffix;
      } else {
        resolvedTag = tag.suffix;
      }
    }

    const register = (node) => {
      if (anchor !== null) this.anchors.set(anchor, node);
      return node;
    };

    if (resolvedTag === null && startMark === null && this.checkToken('scalar')) {
      token = this.peekToken();
      if (token.plain) {
        const node = new ScalarNode(null, token.value, token.style, true,
          token.startMark, token.endMark);
        node.tag = resolveScalarTag(token.value, true);
        this.getToken();
        return node;
      }
    }

    if (this.checkToken('scalar')) {
      token = this.getToken();
      const node = new ScalarNode(null, token.value, token.style, token.plain,
        token.startMark, token.endMark);
      if (resolvedTag === null || resolvedTag === '!') {
        node.tag = resolveScalarTag(token.value, token.plain);
      } else {
        node.tag = resolvedTag;
      }
      return register(node);
    }

    if (block && indentlessSequence && this.checkToken('block-entry')) {
      // sequence without BLOCK-SEQUENCE-START
      token = this.peekToken();
      const items = [];
      const node = new SequenceNode(
        resolvedTag === null || resolvedTag === '!' ? TAG_SEQ : resolvedTag,
        items, false);
      node.startMark = token.startMark;
      while (this.checkToken('block-entry')) {
        this.getToken();
        if (this.checkToken('block-entry', 'block-end', 'key', 'value', 'document-end', 'stream-end')) {
          items.push(this.emptyScalar());
        } else {
          items.push(this.parseNode(true));
        }
      }
      return register(node);
    }

    if (this.checkToken('block-sequence-start')) {
      const startTok = this.getToken();
      const items = [];
      const node = new SequenceNode(
        resolvedTag === null || resolvedTag === '!' ? TAG_SEQ : resolvedTag,
        items, false);
      node.startMark = startTok.startMark;
      while (this.checkToken('block-entry')) {
        this.getToken();
        if (this.checkToken('block-entry', 'block-end')) {
          items.push(this.emptyScalar());
        } else {
          items.push(this.parseNode(true));
        }
      }
      if (!this.checkToken('block-end')) {
        const t = this.peekToken();
        throw new ParserError('while parsing a block collection', startTok.startMark,
          `expected <block end>, but found '${t.kind}'`, t.startMark);
      }
      this.getToken();
      return register(node);
    }

    if (this.checkToken('block-mapping-start')) {
      const startTok = this.getToken();
      const pairs = [];
      const node = new MappingNode(
        resolvedTag === null || resolvedTag === '!' ? TAG_MAP : resolvedTag,
        pairs, false);
      node.startMark = startTok.startMark;
      while (this.checkToken('key')) {
        this.getToken();
        let keyNode;
        if (this.checkToken('key', 'value', 'block-end')) {
          keyNode = this.emptyScalar();
        } else {
          keyNode = this.parseNode(true);
        }
        let valueNode;
        if (this.checkToken('value')) {
          this.getToken();
          if (this.checkToken('key', 'value', 'block-end')) {
            valueNode = this.emptyScalar();
          } else {
            valueNode = this.parseNode(true, true);
          }
        } else {
          valueNode = this.emptyScalar();
        }
        pairs.push([keyNode, valueNode]);
      }
      if (!this.checkToken('block-end')) {
        const t = this.peekToken();
        throw new ParserError('while parsing a block mapping', startTok.startMark,
          `expected <block end>, but found '${t.kind}'`, t.startMark);
      }
      this.getToken();
      return register(node);
    }

    if (this.checkToken('flow-sequence-start')) {
      const startTok = this.getToken();
      const items = [];
      const node = new SequenceNode(
        resolvedTag === null || resolvedTag === '!' ? TAG_SEQ : resolvedTag,
        items, true);
      node.startMark = startTok.startMark;
      this.parseFlowSequenceItems(items, startTok);
      return register(node);
    }

    if (this.checkToken('flow-mapping-start')) {
      const startTok = this.getToken();
      const pairs = [];
      const node = new MappingNode(
        resolvedTag === null || resolvedTag === '!' ? TAG_MAP : resolvedTag,
        pairs, true);
      node.startMark = startTok.startMark;
      this.parseFlowMappingPairs(pairs, startTok);
      return register(node);
    }

    if (resolvedTag !== null || anchor !== null) {
      // empty scalar with properties
      const t = this.peekToken();
      const node = new ScalarNode(null, '', null, true, t.startMark, t.endMark);
      if (resolvedTag === null || resolvedTag === '!') {
        node.tag = resolveScalarTag('', true);
      } else {
        node.tag = resolvedTag;
      }
      return register(node);
    }

    const t = this.peekToken();
    throw new ParserError('while parsing a node', startMark,
      `expected the node content, but found '${t.kind}'`, t.startMark);
  }

  parseFlowSequenceItems(items, startTok) {
    let first = true;
    while (true) {
      if (this.checkToken('flow-sequence-end')) {
        this.getToken();
        return;
      }
      if (!first) {
        if (this.checkToken('flow-entry')) {
          this.getToken();
          if (this.checkToken('flow-sequence-end')) {
            this.getToken();
            return;
          }
        } else {
          const t = this.peekToken();
          throw new ParserError('while parsing a flow sequence', startTok.startMark,
            `expected ',' or ']', but got '${t.kind}'`, t.startMark);
        }
      }
      first = false;
