  i++; // '-'
  const month = parseInt(take(2), 10);
  i++; // '-'
  const day = parseInt(take(2), 10);
  if (!validDate(year, month, day)) timestampError(node);
  if (i >= n) {
    return new YAMLDate(year, month, day);
