function constructBinary(value, node) {
  let cleaned = '';
  for (const ch of value) {
    if (ch !== ' ' && ch !== '\t' && ch !== '\n' && ch !== '\r' &&
      ch !== '' && ch !== ' ' && ch !== ' ') {
